cd /Users/nasarissa/verify-blind-runs/run4/duration-lib; node --test > /tmp/v002.log 2>&1; echo exit=$?; tail -12 /tmp/v002.log
P=$(mktemp -d); cat > $P/probe.js <<'EOF'
const { formatDuration } = require(process.argv[2]);
for (const v of [0,1,999,999.5,1000,1001,1050,1250,1500,1949,1950,1999,9999,59000,59949,59950,59999,60000,60999,61000,90000,3599999,3600000,86400000,-0,-1,-0.001,NaN,Infinity,'1500',null,undefined]) {
  let r; try { r = JSON.stringify(formatDuration(v)); } catch (e) { r = 'throws ' + e.constructor.name; }
  console.log(String(v).padEnd(10), r);
}
EOF
node $P/probe.js "$PWD/src/duration.js"; echo "PROBE=$P"

